/* In-page Notification Centre: real application activity, no OS permission prompt. */
(() => {
const key='po-notifications-v1';let items=[],serial=0;
try{const stored=JSON.parse(localStorage.getItem(key)||'[]');if(Array.isArray(stored))items=stored.filter(n=>typeof n.title==='string'&&typeof n.body==='string'&&Number.isFinite(n.time)&&n.time>0&&n.time<Date.now()+86400000).slice(0,30).map(n=>({...n,id:++serial,title:n.title.slice(0,120),body:n.body.slice(0,300),read:!!n.read,action:['files','messages','safari','games'].includes(n.action)?n.action:null}))}catch{}
const button=document.createElement('button');button.id='notifications-toggle';button.setAttribute('aria-label','Notification Centre');button.setAttribute('aria-controls','notification-centre');button.setAttribute('aria-expanded','false');button.innerHTML='<svg viewBox="0 0 24 24" aria-hidden="true"><path d="M6 9a6 6 0 0112 0v5l2 3H4l2-3V9Zm4 11h4" fill="none" stroke="currentColor" stroke-width="1.6" stroke-linecap="round" stroke-linejoin="round"/></svg><span hidden></span>';document.querySelector('.menu-right').prepend(button);
const panel=document.createElement('aside');panel.id='notification-centre';panel.hidden=true;panel.setAttribute('aria-labelledby','notifications-heading');panel.innerHTML='<header><div><small>YOUR DESKTOP</small><h2 id="notifications-heading">Notifications</h2></div><button id="notifications-close" aria-label="Close notifications">×</button></header><div class="notifications-tools"><span id="notifications-count"></span><button id="notifications-clear">Clear all</button></div><div id="notifications-list"></div><footer>Activity from this portfolio · saved in this browser</footer>';document.querySelector('#desktop').append(panel);
function persist(){try{localStorage.setItem(key,JSON.stringify(items))}catch{}}
function badge(){const unread=items.filter(n=>!n.read).length,b=button.querySelector('span');b.hidden=!unread;b.textContent=String(unread);button.setAttribute('aria-label','Notification Centre'+(unread?', '+unread+' unread':''))}
function render(){const list=panel.querySelector('#notifications-list');list.replaceChildren();panel.querySelector('#notifications-count').textContent=items.length+' '+(items.length===1?'notification':'notifications');panel.querySelector('#notifications-clear').disabled=!items.length;if(!items.length){const empty=document.createElement('p');empty.className='notifications-empty';empty.textContent='All caught up. New activity will appear here.';list.append(empty)}for(const item of items){const row=document.createElement('article'),art=document.createElement('img'),copy=document.createElement('button'),title=document.createElement('strong'),body=document.createElement('p'),time=document.createElement('time'),dismiss=document.createElement('button');art.src=item.action==='games'?'assets/ps-app/icon.svg':'assets/tahoe/'+(item.action==='messages'?'messages':item.action==='safari'?'safari':item.action==='games'?'games':'finder')+'.svg';art.alt='';title.textContent=item.title;body.textContent=item.body;time.dateTime=new Date(item.time).toISOString();time.textContent=new Intl.DateTimeFormat('en-GB',{hour:'2-digit',minute:'2-digit',day:'numeric',month:'short'}).format(new Date(item.time));copy.append(title,body,time);copy.onclick=()=>{close();if(item.action==='messages')window.openMessages?.();else if(item.action==='safari')window.openSafari?.();else if(item.action==='games')location.href='games.html';else window.PortfolioFinder?.open()};dismiss.textContent='×';dismiss.setAttribute('aria-label','Dismiss '+item.title);dismiss.onclick=()=>{items=items.filter(n=>n.id!==item.id);persist();render();badge()};row.append(art,copy,dismiss);list.append(row)}}
function close(){panel.hidden=true;button.setAttribute('aria-expanded','false')}
function open(){if(typeof isUnlocked!=='undefined'&&!isUnlocked)return;panel.hidden=false;button.setAttribute('aria-expanded','true');items.forEach(n=>n.read=true);persist();render();badge();window.PortfolioMotion?.spring(panel,.96,1);panel.querySelector('#notifications-close').focus()}
function add({title='Finder',body='',action='files'}={}){title=String(title).slice(0,120);body=String(body).slice(0,300);if(!body)return;const previous=items[0];if(previous?.title===title&&previous?.body===body&&Date.now()-previous.time<1500)return;items.unshift({id:++serial,title,body,action:['files','messages','safari','games'].includes(action)?action:'files',time:Date.now(),read:!panel.hidden});items=items.slice(0,30);persist();badge();if(!panel.hidden)render()}
button.onclick=()=>panel.hidden?open():close();panel.querySelector('#notifications-close').onclick=()=>{close();button.focus()};panel.querySelector('#notifications-clear').onclick=()=>{items=[];persist();render();badge()};document.addEventListener('pointerdown',e=>{if(!panel.hidden&&!panel.contains(e.target)&&!button.contains(e.target))close()});panel.addEventListener('keydown',e=>{if(e.key==='Escape'){e.preventDefault();e.stopPropagation();close();button.focus()}});document.querySelector('#lock-button').addEventListener('click',close);
window.addEventListener('portfolio:notification',e=>add(e.detail));
const toast=document.querySelector('#toast');if(toast)new MutationObserver(()=>{const title=toast.querySelector('.toast-copy strong')?.textContent||'Finder',body=toast.querySelector('.toast-copy span')?.textContent;if(body)add({title,body,action:'files'})}).observe(toast,{childList:true,subtree:true});
badge();if(!items.length)add({title:'Finder is ready',body:'Browse project folders, preview pictures and play videos. You can also open a read-only folder from your device.',action:'files'});
window.PortfolioNotifications={add,open,close,get items(){return items.map(n=>({...n}))}};
})();
